WITH flattened_attrs AS (SELECT id, items, attributes, AGGREGATE(items, 0D, (acc, item) -> acc + item.qty * item.price, acc -> ROUND(acc, 2)) AS items_total, ARRAY_CONTAINS(MAP_KEYS(attributes), 'device') AS has_device, ARRAY_MAX(TRANSFORM(items, item -> item.price)) AS max_item_price, COALESCE(attributes['device'], 'direct') AS device_or_default, SIZE(FILTER(items, item -> item.qty >= 3)) AS bulk_lines FROM carts) SELECT CASE WHEN items_total >= 1430 THEN 'HIGH' ELSE 'LOW' END AS items_total_tier, CASE WHEN max_item_price >= 218 THEN 'PREMIUM' ELSE 'STANDARD' END AS max_item_price_tier, CASE WHEN bulk_lines >= 2 THEN 'LARGE' ELSE 'SMALL' END AS bulk_lines_tier, ROUND(AVG(max_item_price), 2) AS avg_max_item_price, ROUND(AVG(bulk_lines), 2) AS avg_bulk_lines, PERCENTILE_APPROX(bulk_lines, 0.5) AS bulk_lines_p50, SUM(max_item_price) AS total_max_item_price, GROUPING(CASE WHEN items_total >= 1430 THEN 'HIGH' ELSE 'LOW' END) AS grouping_level FROM flattened_attrs GROUP BY ROLLUP (CASE WHEN items_total >= 1430 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN max_item_price >= 218 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN bulk_lines >= 2 THEN 'LARGE' ELSE 'SMALL' END) HAVING ROUND(AVG(bulk_lines), 2) >= 0 ORDER BY max_item_price_tier DESC NULLS FIRST;
